import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { BENCHMARK_PATH_FIXTURE_URL, BENCHMARK_PATH_SCENARIOS, runBenchmarkPathScenario } from "./fixtures/native-benchmark-path-harness.mjs";

// The golden record of what the Harbor benchmark runner sends and records. It was written before Native reply streaming
// existed and is never regenerated by a change elsewhere: a difference here means the benchmark path changed. It was
// rewritten once on purpose (2026-10-29) when the runner took the app's configuration (src/native-configuration.mjs): every
// request lost service_tier "fast" (no tier by default), its instructions gained the developer text after the system prompt
// (so prompt_cache_key changed), and what is derived from them followed (message counts, request bytes and hashes,
// requestedServiceTier null); nothing else changed. Later that day each turn's usage update gained its context reading (the last
// request's usage, which the app's context meter and automatic compaction read): an update the runner only records, with no request,
// payload or fetch changed. Then the developer text lost its web-research sentence (113 characters, dropped for the app and the
// runner alike on the second review): the instructions and what follows from them changed (prompt_cache_key, request bytes, the
// developer and prefix sizes and hashes in the request metrics); nothing else did.
const fixture=JSON.parse(await readFile(BENCHMARK_PATH_FIXTURE_URL,"utf8"));

test("Harbor Native runner never opts into reply streaming",async()=>{
  for(const file of ["trebell-native-runner.mjs","native-harbor-run.mjs"]){
    const source=await readFile(new URL("../benchmarks/harbor/"+file,import.meta.url),"utf8");
    for(const name of ["streamDrafts","NATIVE_REPLY_STREAM","onStream","streamChat"])assert.equal(source.includes(name),false,"the runner must not mention "+name+" ("+file+")");
  }
  // It sends through the app's own provider turn (src/native-provider-turn.mjs), with no draft observer on the request.
  const run=await readFile(new URL("../benchmarks/harbor/native-harbor-run.mjs",import.meta.url),"utf8");
  assert.match(run,/const response=await nativeProviderTurn\(manager,sent\);/);
});

test("the golden record covers every scripted branch of the runner's provider path",()=>{
  assert.deepEqual(Object.keys(fixture).sort(),Object.keys(BENCHMARK_PATH_SCENARIOS).sort());
  assert.deepEqual(fixture.websocket_tool_then_answer.requestOrder,["ws","ws"]);
  assert.deepEqual(fixture.sse_tool_then_answer.requestOrder,["https","https"]);
  assert.deepEqual(fixture.websocket_server_error_then_https.requestOrder,["ws","https"]);
  assert.deepEqual(fixture.gate_lane_verdict.requestOrder,["ws","ws","ws","ws"]);
  assert.deepEqual(fixture.websocket_drop_after_text_then_https.requestOrder,["ws","https"]);
  assert.equal(JSON.parse(fixture.gate_lane_verdict.wsPayloads[3]).stream_id,"gate-trebell-harbor");
  assert.ok(fixture.gate_lane_verdict.events.some(event=>event.name==="native.completion.gate"));
  for(const name of Object.keys(fixture)){assert.equal(fixture[name].error,null,name);assert.equal(fixture[name].unusedReplies,0,name)}
  const commentary=BENCHMARK_PATH_SCENARIOS.websocket_tool_then_answer.replies[0].events.find(event=>event.type==="response.output_item.added"&&event.item?.phase==="commentary");assert.ok(commentary);
  const dropped=BENCHMARK_PATH_SCENARIOS.websocket_drop_after_text_then_https.replies[0];assert.equal(dropped.drop,true);assert.ok(dropped.events.filter(event=>event.type==="response.output_text.delta").length>=2);
});

// The API answers include:["reasoning.encrypted_content"] with reasoning items that carry it, and the runner keeps them for a
// request rebuilt in full. None of these paths rebuilds a turn after its reasoning came back, so each sends what the record holds.
test("reasoning that comes back with its encrypted_content changes nothing the runner sends on its scripted paths",async()=>{
  for(const name of Object.keys(BENCHMARK_PATH_SCENARIOS)){
    const record=await runBenchmarkPathScenario(name,{encryptedReasoning:true});
    assert.equal(record.error,null,name);
    assert.deepEqual(record.wsPayloads,fixture[name].wsPayloads,name);
    assert.deepEqual(record.fetches,fixture[name].fetches,name);
  }
  const kept=(await runBenchmarkPathScenario("websocket_tool_then_answer",{encryptedReasoning:true})).responses[0].reasoningItems;
  assert.deepEqual(kept,[{before:"message",item:{type:"reasoning",id:"rs_a1",summary:[],encrypted_content:"enc-rs_a1"}}],"the runner's turns return the reasoning to keep");
});

for(const name of Object.keys(BENCHMARK_PATH_SCENARIOS)){
  test("Harbor Native runner provider path matches its golden record: "+name,async()=>{
    const record=await runBenchmarkPathScenario(name);
    assert.deepEqual(record.requestOrder,fixture[name].requestOrder);
    assert.deepEqual(record.wsConnections,fixture[name].wsConnections);
    assert.deepEqual(record.wsPayloads,fixture[name].wsPayloads);
    assert.deepEqual(record.fetches,fixture[name].fetches);
    assert.deepEqual(record.responses.map(response=>response.telemetry),fixture[name].responses.map(response=>response.telemetry));
    assert.deepEqual(record,fixture[name]);
  });
}
